// The ::credentials-required signal is emitted when the @source
// requires credentials to connect to (possibly remote)
// data store. The credentials can be passed to the source using
// e_source_invoke_authenticate() function. The signal is emitted in
// the thread-default main context from the time the @registry was created.
//
// Note: This is just a proxy signal for the ESource::credentials-required signal.
func (x *SourceRegistry) ConnectCredentialsRequired(cb *func(SourceRegistry, uintptr, SourceCredentialsReason, string, gio.TlsCertificateFlags, uintptr)) uint32 {
	cbPtr := uintptr(unsafe.Pointer(cb))
	if cbRefPtr, ok := glib.GetCallback(cbPtr); ok {
		return gobject.SignalConnect(x.GoPointer(), "credentials-required", cbRefPtr)
	}

	fcb := func(clsPtr uintptr, SourceVarp uintptr, ReasonVarp SourceCredentialsReason, CertificatePemVarp string, CertificateErrorsVarp gio.TlsCertificateFlags, OpErrorVarp uintptr) {
		fa := SourceRegistry{}
		fa.Ptr = clsPtr
		cbFn := *cb

		cbFn(fa, SourceVarp, ReasonVarp, CertificatePemVarp, CertificateErrorsVarp, OpErrorVarp)

	}
	cbRefPtr := purego.NewCallback(fcb)
	glib.SaveCallback(cbPtr, cbRefPtr)
	return gobject.SignalConnect(x.GoPointer(), "credentials-required", cbRefPtr)
}

